271→	// Read files from the agent's working directory (for rendering artifacts)
272→	app.get("/api/agent-files", requireAuth, apiRateLimit, async (req, res) => {
273→		const rawPath = req.query.path as string;
274→		if (!rawPath) {
275→			return res.status(400).json({ error: "Path required" });
276→		}
277→		// Resolve relative paths against the user's active CWD
278→		const userId = (req as any).user?.userId;
279→		const cwd = activeUserCwds.get(userId);
280→		let filePath: string;
281→		if (path.isAbsolute(rawPath)) {
282→			filePath = rawPath;
283→		} else if (cwd) {
284→			filePath = path.resolve(cwd, rawPath);
285→		} else {
286→			return res.status(400).json({ error: "Absolute path required (no active CWD)" });
287→		}
288→		// Only allow renderable file types
289→		const ext = path.extname(filePath).slice(1).toLowerCase();
290→		if (!RENDERABLE_EXTENSIONS.has(ext)) {
291→			return res.status(400).json({ error: "Unsupported file type" });
292→		}
293→		// 1.8 Path traversal fix: resolve symlinks and use path.sep to prevent prefix attacks.
294→		// Allow temp directory files — agents commonly generate outputs there (python-pptx, etc.).
295→		if (cwd) {
296→			try {
297→				const realFile = await fs.realpath(filePath);
298→				const realCwd = await fs.realpath(cwd);
299→				const inTempDir =
300→					realFile.startsWith("/tmp/") ||
301→					realFile.startsWith("/private/tmp/"); // macOS: /tmp → /private/tmp
302→				if (
303→					!inTempDir &&
304→					!realFile.startsWith(realCwd + path.sep) &&
305→					realFile !== realCwd
306→				) {
307→					return res.status(403).json({ error: "Path is outside working directory" });
308→				}
309→				filePath = realFile;
310→			} catch {
311→				return res.status(404).json({ error: "File not found" });
312→			}
313→		}
314→		try {
315→			// PPTX: convert to slide images server-side via LibreOffice
316→			if (ext === "pptx" || ext === "ppt") {
317→				try {
318→					const { convertPptxToSlideImages } = await import("./services/pptx-converter.js");
319→					const [slides, rawBuffer] = await Promise.all([
320→						convertPptxToSlideImages(filePath),
321→						fs.readFile(filePath),
322→					]);
323→					res.json({ slides, raw: rawBuffer.toString("base64"), encoding: "slides" });
324→					return;
325→				} catch (convErr: any) {
326→					// LibreOffice/pdftoppm not installed — fall back to raw base64
327→					console.warn("[agent-files] PPTX conversion failed, serving raw binary:", convErr.message);
328→					const buffer = await fs.readFile(filePath);
329→					res.json({ content: buffer.toString("base64"), encoding: "base64" });
330→					return;
331→				}
332→			}
333→
334→			const isBinary = BINARY_EXTENSIONS.has(ext);
335→			if (isBinary) {
336→				const buffer = await fs.readFile(filePath);
337→				const base64Content = buffer.toString("base64");
338→				res.json({ content: base64Content, encoding: "base64" });
339→			} else {
340→				const content = await fs.readFile(filePath, "utf-8");
341→				res.json({ content, encoding: "text" });
342→			}
343→		} catch (err: any) {
344→			console.error("[agent-files] Error serving file:", err.message);
345→			res.status(404).json({ error: "File not found" });
346→		}
