353→	wss.on("connection", async (ws, req) => {
354→		// Auth user is attached by the upgrade handler
355→		const user = (req as any).__authUser;
356→		console.log(`[server] New WebSocket connection from ${user?.email || "unknown"}`);
357→
358→		// 1.7 Enforce per-user WebSocket connection limit
359→		if (user?.userId) {
360→			const count = wsConnectionCounts.get(user.userId) || 0;
361→			if (count >= WS_MAX_PER_USER) {
362→				console.warn(`[server] WebSocket limit exceeded for ${user.email} (${count}/${WS_MAX_PER_USER})`);
363→				ws.close(4029, "Too many connections");
364→				return;
365→			}
366→			wsConnectionCounts.set(user.userId, count + 1);
367→			ws.on("close", () => {
368→				const current = wsConnectionCounts.get(user.userId) || 1;
369→				if (current <= 1) {
370→					wsConnectionCounts.delete(user.userId);
371→				} else {
372→					wsConnectionCounts.set(user.userId, current - 1);
373→				}
374→			});
375→		}
