377→		// Buffer messages that arrive before the bridge's message handler is
378→		// registered. The async DB queries below (session ownership, profile
379→		// resolution) can take long enough for the client's first message
380→		// (get_state) to arrive and be silently dropped.
381→		const earlyMessages: Buffer[] = [];
382→		const earlyHandler = (data: Buffer) => earlyMessages.push(data);
383→		ws.on("message", earlyHandler);
384→
385→		// Parse bridge options from query params
386→		const url = new URL(req.url || "/", `http://localhost:${PORT}`);
387→		const options: BridgeOptions = {};
388→		if (url.searchParams.has("cwd")) options.cwd = url.searchParams.get("cwd")!;
389→		if (url.searchParams.has("provider")) options.provider = url.searchParams.get("provider")!;
390→		if (url.searchParams.has("model")) options.model = url.searchParams.get("model")!;
391→
392→		let sessionId = url.searchParams.get("sessionId") || undefined;
393→
394→		// Validate session ownership before allowing reconnection
395→		if (sessionId) {
396→			const sessionResult = await db.query<{ user_id: string }>(
397→				"SELECT user_id FROM sessions WHERE id = $1 AND deleted_at IS NULL",
398→				[sessionId],
399→			);
400→			if (sessionResult.rows.length === 0) {
401→				// Session not in DB yet (async client save may be in-flight).
402→				// Keep sessionId so SdkBridge can check the session pool for
403→				// reattachment. Pool-level userId check prevents cross-user access.
404→			} else if (sessionResult.rows[0].user_id !== user.userId) {
405→				console.warn(`[server] User ${user.userId} attempted to access session ${sessionId} owned by ${sessionResult.rows[0].user_id}`);
406→				ws.close(4003, "Session not owned by authenticated user");
407→				return;
408→			}
409→		}
410→
411→		// Track CWD for agent-files endpoint (use explicit cwd or fall back to server CWD)
412→		activeUserCwds.set(user.userId, options.cwd || process.cwd());
413→
414→		// Resolve agent profile if specified
415→		const agentProfileId = url.searchParams.get("agentProfileId") || undefined;
416→		let profileSkillIds: string[] | undefined;
417→		let profileFileIds: string[] | undefined;
418→
419→		if (agentProfileId) {
420→			try {
421→				const profileResult = await db.query<AgentProfileRow>(
422→					`SELECT * FROM agent_profiles WHERE id = $1
423→					 AND ((scope = 'platform')
424→					   OR (scope = 'team' AND owner_id = $2)
425→					   OR (scope = 'user' AND owner_id = $3))`,
426→					[agentProfileId, user.teamId, user.userId],
427→				);
428→				const profile = profileResult.rows[0];
429→				if (profile) {
430→					// Profile fields applied as defaults (explicit query params override)
431→					if (!options.provider && profile.provider) options.provider = profile.provider;
432→					if (!options.model && profile.model_id) options.model = profile.model_id;
433→					// System prompt from profile
434→					if (profile.prompt_mode === "append") {
435→						options.appendSystemPrompt = profile.system_prompt;
436→					} else {
437→						options.systemPrompt = profile.system_prompt;
438→					}
439→					profileSkillIds = profile.skill_ids ?? undefined;
440→					profileFileIds = profile.file_ids ?? undefined;
441→					// Increment use count (fire-and-forget)
442→					db.query(
443→						`UPDATE agent_profiles SET use_count = use_count + 1 WHERE id = $1`,
444→						[agentProfileId],
445→					).catch(() => {});
446→					console.log(`[server] Using agent profile "${profile.name}" (${agentProfileId})`);
447→				} else {
448→					console.warn(`[server] Agent profile ${agentProfileId} not found or not accessible`);
449→				}
450→			} catch (err) {
451→				console.error("[server] Failed to resolve agent profile:", err);
452→			}
453→		}
454→
455→		// Create SDK bridge
456→		const sdkOptions: SdkBridgeOptions = {
457→			...options,
458→			user: {
459→				userId: user.userId,
460→				teamId: user.teamId,
461→				email: user.email,
462→				role: user.role,
463→			},
464→			sessionId,
465→			sessionPool,
466→			crypto,
467→			db,
468→			storage: storageService,
469→			sessionStatusService,
470→			outputBufferService,
471→			profileSkillIds,
472→			profileFileIds,
473→			agentProfileId,
474→			serverPort: PORT,
475→		};
476→		const bridge = new SdkBridge(ws, sdkOptions);
477→		bridge.start();
478→
479→		// Stop buffering — the bridge's message handler is now registered.
480→		// Replay any messages that arrived during the async setup above.
481→		ws.off("message", earlyHandler);
482→		for (const msg of earlyMessages) {
483→			ws.emit("message", msg);
484→		}
485→	});
