487→	// WebSocket upgrade handler with JWT authentication
488→	const handleUpgrade = (req: any, socket: any, head: any) => {
489→		const pathname = new URL(req.url || "/", `http://localhost:${PORT}`).pathname;
490→		if (pathname === "/ws") {
491→			// Authenticate WebSocket upgrade
492→			const user = authenticateWsUpgrade(req);
493→			if (!user) {
494→				socket.write("HTTP/1.1 401 Unauthorized\r\n\r\n");
495→				socket.destroy();
496→				return;
497→			}
498→
499→			// Attach user to request for the connection handler
500→			req.__authUser = user;
501→
502→			wss.handleUpgrade(req, socket, head, (ws) => {
503→				wss.emit("connection", ws, req);
504→			});
505→		} else if (isDev) {
506→			// In dev mode, let Vite handle non-/ws upgrades (HMR)
507→		} else {
508→			socket.destroy();
509→		}
510→	};
511→
512→	if (isDev) {
513→		// In dev mode, use Vite's dev server as middleware.
514→		const { createServer: createViteServer } = await import("vite");
515→		const vite = await createViteServer({
516→			configFile: path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../vite.config.ts"),
517→			root: path.resolve(path.dirname(fileURLToPath(import.meta.url)), ".."),
518→			server: {
519→				middlewareMode: true,
520→				hmr: {
521→					server,
522→				},
523→			},
524→		});
