526→		// Vite middleware AFTER API routes so /api/* is handled first
527→		app.use(vite.middlewares);
528→
529→		// Vite registers its own upgrade handler for HMR. We need a single
530→		// dispatcher that routes /ws to us and everything else to Vite.
531→		const viteUpgradeListeners = server.listeners("upgrade").slice();
532→		server.removeAllListeners("upgrade");
533→
534→		server.on("upgrade", (req: any, socket: any, head: any) => {
535→			const pathname = new URL(req.url || "/", `http://localhost:${PORT}`).pathname;
536→			if (pathname === "/ws") {
537→				handleUpgrade(req, socket, head);
538→			} else {
539→				// Forward to Vite's HMR upgrade handler(s)
540→				for (const listener of viteUpgradeListeners) {
541→					(listener as Function).call(server, req, socket, head);
542→				}
543→			}
544→		});
545→	} else {
546→		// In production, serve the built files
547→		const distPath = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../dist");
548→		app.use(express.static(distPath));
549→
550→		// SPA fallback — but not for /api/* routes
551→		app.get("/{*path}", (_req, res) => {
552→			res.sendFile(path.join(distPath, "index.html"));
553→		});
554→
555→		server.on("upgrade", handleUpgrade);
556→	}
