558→	// --- OAuth callback servers ---
559→	// Each OAuth provider has a fixed localhost redirect URI. We start lightweight
560→	// HTTP servers on the required ports to capture the redirect and relay the
561→	// authorization code to the opener window via postMessage.
562→	const oauthCallbackServers: Array<ReturnType<typeof createServer>> = [];
563→
564→	function startOAuthCallbackServer(port: number, path: string, envOverride?: string) {
565→		if (envOverride && process.env[envOverride]) return; // custom redirect, skip
566→		const srv = createServer((req, res) => {
567→			const url = new URL(req.url || "", `http://localhost:${port}`);
568→			if (url.pathname === path) {
569→				res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
570→				res.end(OAUTH_CALLBACK_HTML);
571→			} else {
572→				res.writeHead(404);
573→				res.end("Not found");
574→			}
575→		});
576→		srv.listen(port, "127.0.0.1", () => {
577→			console.log(`[server] OAuth callback on http://localhost:${port}${path}`);
578→		});
579→		srv.on("error", (err: NodeJS.ErrnoException) => {
580→			if (err.code === "EADDRINUSE") {
581→				console.warn(`[server] Port ${port} in use — OAuth callback skipped (manual paste still works)`);
582→			} else {
583→				console.error(`[server] OAuth callback server error (port ${port}):`, err);
584→			}
585→		});
586→		oauthCallbackServers.push(srv);
587→	}
588→
589→	// OpenAI: http://localhost:1455/auth/callback
590→	startOAuthCallbackServer(1455, "/auth/callback", "OAUTH_OPENAI_REDIRECT_URI");
591→	// Google Antigravity: http://localhost:51121/oauth-callback
592→	startOAuthCallbackServer(51121, "/oauth-callback", "OAUTH_ANTIGRAVITY_REDIRECT_URI");
593→
594→	// Graceful shutdown
595→	const gracefulShutdown = async (signal: string) => {
596→		console.log(`[server] Received ${signal}, shutting down gracefully...`);
597→		await taskQueueService.shutdown();
598→		await sessionPool.shutdown();
599→		for (const srv of oauthCallbackServers) srv.close();
600→		server.close(() => {
601→			console.log("[server] HTTP server closed");
602→			process.exit(0);
603→		});
604→		// Force exit after 10s if shutdown hangs
605→		setTimeout(() => process.exit(1), 10_000).unref();
606→	};
607→
608→	process.on("SIGTERM", () => gracefulShutdown("SIGTERM"));
609→	process.on("SIGINT", () => gracefulShutdown("SIGINT"));
610→
611→	server.listen(PORT, () => {
612→		console.log(`[server] Chatbot Platform running at http://localhost:${PORT}`);
613→		if (isDev) {
614→			console.log("[server] Running in development mode with Vite HMR");
615→		}
616→	});
617→}
618→
619→main().catch((err) => {
620→	console.error("Failed to start server:", err);
621→	process.exit(1);
622→});
