229→	private getFilteredModels(): Array<{ provider: string; id: string; model: any }> {
230→		// Collect models from allowed known providers only
231→		const allModels: Array<{ provider: string; id: string; model: any }> = [];
232→		const knownProviders = getProviders();
233→
234→		for (const provider of knownProviders) {
235→			if (!ModelSelector.ALLOWED_PROVIDERS.has(provider)) continue;
236→			const allowlist = ModelSelector.PROVIDER_MODEL_ALLOWLIST[provider];
237→			const models = getModels(provider as any);
238→			for (const model of models) {
239→				if (allowlist && !allowlist.has(model.id)) continue;
240→				allModels.push({ provider, id: model.id, model });
241→			}
242→		}
243→
244→		// Add custom provider models
245→		for (const model of this.customProviderModels) {
246→			allModels.push({ provider: model.provider, id: model.id, model });
247→		}
248→
249→		// Filter models based on search and capability filters
250→		let filteredModels = allModels;
251→
252→		// Apply search filter
253→		if (this.searchQuery) {
254→			filteredModels = filteredModels.filter(({ provider, id, model }) => {
255→				const searchTokens = this.searchQuery
256→					.toLowerCase()
257→					.split(/\s+/)
258→					.filter((t) => t);
259→				const searchText = `${provider} ${id} ${model.name}`.toLowerCase();
260→				return searchTokens.every((token) => searchText.includes(token));
261→			});
262→		}
263→
264→		// Apply capability filters
265→		if (this.filterThinking) {
266→			filteredModels = filteredModels.filter(({ model }) => model.reasoning);
267→		}
268→		if (this.filterVision) {
269→			filteredModels = filteredModels.filter(({ model }) => model.input.includes("image"));
270→		}
271→
272→		// Sort: current model first, then by provider
273→		filteredModels.sort((a, b) => {
274→			const aIsCurrent = modelsAreEqual(this.currentModel, a.model);
275→			const bIsCurrent = modelsAreEqual(this.currentModel, b.model);
276→			if (aIsCurrent && !bIsCurrent) return -1;
277→			if (!aIsCurrent && bIsCurrent) return 1;
278→			return a.provider.localeCompare(b.provider);
279→		});
280→
281→		return filteredModels;
282→	}
