 63→/**
 64→ * Preferred default models in priority order.
 65→ * When no explicit model is chosen, pick the first match from available models.
 66→ */
 67→const PREFERRED_DEFAULT_MODELS = [
 68→	{ provider: "anthropic", id: "claude-sonnet-4-5" },
 69→	{ provider: "anthropic", id: "claude-sonnet-4-6" },
 70→	{ provider: "anthropic", id: "claude-haiku-4-5" },
 71→	{ provider: "google", id: "gemini-2.5-flash" },
 72→	{ provider: "xai", id: "grok-4-fast" },
 73→	{ provider: "zai", id: "glm-4.7" },
 74→	{ provider: "minimax", id: "MiniMax-M2.5" },
 75→];
 76→
 77→/**
 78→ * Pick the best default model from a list of available models.
 79→ * Tries PREFERRED_DEFAULT_MODELS first (only from configured providers),
 80→ * then falls back to the first model from any configured provider, then available[0].
 81→ */
 82→function pickDefaultModel<T extends { provider: string; id: string }>(
 83→	available: T[],
 84→	configuredProviders: Set<string>,
 85→): T | undefined {
 86→	for (const pref of PREFERRED_DEFAULT_MODELS) {
 87→		const match = available.find(
 88→			(m) => m.provider === pref.provider && m.id === pref.id && configuredProviders.has(m.provider),
 89→		);
 90→		if (match) return match;
 91→	}
 92→	return available.find((m) => configuredProviders.has(m.provider)) ?? available[0];
 93→}
