114→export class SdkBridge {
115→	private ws: WebSocket;
116→	private options: SdkBridgeOptions;
117→	private user: AuthUser;
118→	private sessionId: string;
119→	private sessionPool: SessionPool;
120→	private crypto: CryptoService;
121→	private db: Database;
122→	private storage: StorageService;
123→	private sessionStatusService: SessionStatusService;
124→	private outputBufferService: OutputBufferService;
125→
126→	// Session state
127→	private session: AgentSession | null = null;
128→	private authStorage: AuthStorage | null = null;
129→	private resourceLoader: DefaultResourceLoader | null = null;
130→	private resolvedSkills: ResolvedSkills | null = null;
131→	private resolvedFiles: ResolvedFiles | null = null;
132→	private memoryToken: string | null = null;
133→	private sessionModel: { id: string; provider: string | null } | null = null;
134→	private conversationHistory: Array<{ role: string; content: any }> | null = null;
135→
136→	// Bridge state
137→	private closed = false;
138→	private detached = false;
139→	private ready = false;
140→	private sessionCreating = false;
141→	private pendingMessages: Array<{ raw: string; parsed: any }> = [];
142→	// Providers explicitly configured via team API keys or user OAuth (via setRuntimeApiKey).
143→	// Used to prefer these over auto-detected providers (e.g., AWS IAM → Bedrock) when
144→	// resolving the default model in sendSyntheticGetState().
145→	private configuredProviders = new Set<string>();
146→	private unsubscribeSession: (() => void) | null = null;
147→
148→	// Extension UI pending promises (for forwarding UI requests to WS client)
149→	private pendingUIRequests = new Map<string, {
150→		resolve: (value: any) => void;
151→		reject: (reason: any) => void;
152→	}>();
153→
154→	constructor(ws: WebSocket, options: SdkBridgeOptions) {
155→		this.ws = ws;
156→		this.options = options;
157→		this.user = options.user;
158→		this.sessionId = options.sessionId || randomUUID();
159→		this.sessionPool = options.sessionPool;
160→		this.crypto = options.crypto;
161→		this.db = options.db;
162→		this.storage = options.storage;
163→		this.sessionStatusService = options.sessionStatusService;
164→		this.outputBufferService = options.outputBufferService;
165→	}
166→
167→	/**
168→	 * Start the bridge: register WebSocket handlers immediately, then
169→	 * async-initialize keys + skills + session.
170→	 */
171→	start(): void {
172→		this.wireUpWebSocket();
173→
174→		this.startAsync().catch((err) => {
175→			console.error("[sdk-bridge] Failed to start:", err);
176→			this.ws.close(1011, "Failed to initialize agent");
177→		});
178→	}
179→
180→	private async startAsync(): Promise<void> {
181→		// Check generating limit before proceeding
182→		const generatingCount = await this.sessionStatusService.getGeneratingCount(this.user.userId, this.db);
183→		if (generatingCount >= 3) {
184→			this.ws.close(4031, "Max 3 concurrent generating sessions");
185→			return;
186→		}
187→
188→		// Run all async prep work in parallel
189→		const [envKeys, , , , memoryContent] = await Promise.all([
190→			// 1. Fetch and inject provider keys + OAuth credentials
191→			new AgentExecutor({ db: this.db, crypto: this.crypto, storage: this.storage })
192→				.buildEnv(this.user.userId, this.user.teamId),
193→
194→			// 2. Resolve skills for this user (filtered by profile if set)
195→			resolveSkillsForUser(
196→				this.db, this.storage, this.user.userId, this.user.teamId,
197→				this.options.profileSkillIds,
198→			).then(skills => {
199→				this.resolvedSkills = skills;
200→				if (skills.skillPaths.length > 0) {

200→				if (skills.skillPaths.length > 0) {
201→					console.log(`[sdk-bridge] Resolved ${skills.skillPaths.length} skill(s)`);
202→				}
203→			}).catch(err => {
204→				console.error("[sdk-bridge] Failed to resolve skills:", err);
205→			}),
206→
207→			// 3. Resolve files from agent profile
208→			(this.options.profileFileIds && this.options.profileFileIds.length > 0
209→				? resolveFilesForUser(
210→					this.db, this.storage, this.user.userId,
211→					this.options.profileFileIds,
212→				).then(files => {
213→					this.resolvedFiles = files;
214→					if (files.filePaths.length > 0) {
215→						console.log(`[sdk-bridge] Resolved ${files.filePaths.length} file(s)`);
216→					}
217→				}).catch(err => {
218→					console.error("[sdk-bridge] Failed to resolve files:", err);
219→				})
220→				: Promise.resolve()
221→			),
222→
223→			// 4. Fetch conversation history + session model for existing sessions
224→			(this.options.sessionId
225→				? Promise.all([
226→					this.db.query<{ role: string; content: any }>(
227→						`SELECT m.role, m.content FROM messages m
228→						 JOIN sessions s ON s.id = m.session_id
229→						 WHERE m.session_id = $1 AND s.user_id = $2
230→						 ORDER BY m.ordinal ASC LIMIT 200`,
231→						[this.options.sessionId, this.user.userId],
232→					).then(result => {
233→						if (result.rows.length > 0) {
234→							this.conversationHistory = result.rows;
235→							console.log(`[sdk-bridge] Fetched ${result.rows.length} history message(s)`);
236→						}
237→					}),
238→					this.db.query<{ model_id: string | null; provider: string | null }>(
239→						`SELECT model_id, provider FROM sessions
240→						 WHERE id = $1 AND user_id = $2 AND deleted_at IS NULL`,
241→						[this.options.sessionId, this.user.userId],
242→					).then(result => {
243→						if (result.rows.length > 0 && result.rows[0].model_id) {
244→							this.sessionModel = {
245→								id: result.rows[0].model_id,
246→								provider: result.rows[0].provider,
247→							};
248→						}
249→					}),
250→				]).catch(err => {
251→					console.error("[sdk-bridge] Failed to fetch conversation history:", err);
252→				})
253→				: Promise.resolve()
254→			),
255→
256→			// 5. Resolve user memories (content string, no temp file)
257→			resolveMemoryContent(this.db, this.user.userId)
258→				.catch(err => {
259→					console.error("[sdk-bridge] Failed to resolve memories:", err);
260→					return { content: null };
261→				}),
262→		]);
263→
264→		// Issue memory token for the extension
265→		this.memoryToken = issueMemoryToken(this.user.userId, this.user.teamId);
266→
267→		// Audit log provider key decryptions (non-blocking)
268→		const providers = Object.keys(envKeys);
269→		if (providers.length > 0) {
270→			const values = providers.map((_, i) => `($1, $2, $${i + 3}, 'decrypt')`).join(", ");
271→			this.db.query(
272→				`INSERT INTO provider_key_audit_log (team_id, user_id, provider, action) VALUES ${values}`,
273→				[this.user.teamId, this.user.userId, ...providers],
274→			).catch(() => {});
275→		}
276→
277→		// Build AuthStorage with runtime API keys from env map
278→		this.authStorage = AuthStorage.inMemory();
279→		for (const [envVar, value] of Object.entries(envKeys)) {
280→			const provider = envVarToProvider(envVar);
281→			if (provider) {
282→				this.authStorage.setRuntimeApiKey(provider, value);
283→				this.configuredProviders.add(provider);
284→			}
285→		}
286→
287→		// Build the system prompt
288→		let systemPrompt: string | undefined;
289→		let appendSystemPrompt: string | undefined;
290→		if (this.options.systemPrompt) {
291→			systemPrompt = this.options.systemPrompt;
292→		} else if (this.options.appendSystemPrompt) {
293→			appendSystemPrompt = this.options.appendSystemPrompt;
294→		}
295→
296→		// Inject conversation history into append system prompt for continuity
297→		if (this.conversationHistory && this.conversationHistory.length > 0) {
298→			const historyBlock = this.formatConversationHistory(this.conversationHistory);
299→			if (systemPrompt) {
300→				systemPrompt = systemPrompt + "\n\n" + historyBlock;
301→			} else if (appendSystemPrompt) {
302→				appendSystemPrompt = appendSystemPrompt + "\n\n" + historyBlock;
303→			} else {
304→				appendSystemPrompt = historyBlock;
305→			}
306→			console.log(`[sdk-bridge] Injected ${this.conversationHistory.length} history messages into system prompt`);
307→		}
308→
309→		// Build extension factories
310→		const extensionFactories: ExtensionFactory[] = [];
311→
312→		// Brave Search extension
313→		if (process.env.BRAVE_SEARCH_API_KEY) {
314→			extensionFactories.push(braveSearchExtension);
315→		}
316→
317→		// Push-to-viewer extension (always available)
318→		extensionFactories.push(pushToViewerExtension);
319→
320→		// Agent memory extension (closure-based, captures token and port)
321→		if (this.memoryToken) {
322→			extensionFactories.push(
323→				createAgentMemoryExtension(this.memoryToken, this.options.serverPort),
324→			);
325→		}
326→
327→		// Build agents files override for memory injection (virtual file, no temp file)
328→		const memContent = memoryContent?.content ?? null;
329→		const agentsFilesOverride = memContent
330→			? (base: { agentsFiles: Array<{ path: string; content: string }> }) => ({
331→				agentsFiles: [
332→					...base.agentsFiles,
333→					{ path: "MEMORY.md", content: memContent },
334→				],
335→			})
336→			: undefined;
337→
338→		// Build file list for agents files override (profile files)
339→		let profileFilesOverride: typeof agentsFilesOverride | undefined;
340→		if (this.resolvedFiles && this.resolvedFiles.filePaths.length > 0) {
341→			const fileContents = await Promise.all(
342→				this.resolvedFiles.filePaths.map(async (filePath) => {
343→					const content = await fs.readFile(filePath, "utf-8");
344→					return { path: path.basename(filePath), content };
345→				}),
346→			);
347→			const baseOverride = agentsFilesOverride;
348→			profileFilesOverride = (base: { agentsFiles: Array<{ path: string; content: string }> }) => {
349→				const withMemory = baseOverride ? baseOverride(base) : base;
350→				return {
351→					agentsFiles: [
352→						...withMemory.agentsFiles,
353→						...fileContents,
354→					],
355→				};
356→			};
357→		}
358→
359→		const finalFilesOverride = profileFilesOverride || agentsFilesOverride;
360→
361→		// Build ResourceLoader
362→		this.resourceLoader = new DefaultResourceLoader({
363→			cwd: this.options.cwd || process.cwd(),
364→			extensionFactories,
365→			additionalSkillPaths: this.resolvedSkills?.skillPaths,
366→			systemPrompt,
367→			appendSystemPrompt,
368→			agentsFilesOverride: finalFilesOverride,
369→			// Don't load user's global/project extensions/skills/themes
370→			noThemes: true,
371→		});
372→		await this.resourceLoader.reload();
373→
374→		// Check for existing session in pool (reconnection)
375→		if (this.options.sessionId) {
376→			const existing = this.sessionPool.get(this.options.sessionId);
377→			if (existing && existing.userId === this.user.userId) {
378→				console.log(`[sdk-bridge] Reattaching to existing session ${this.options.sessionId}`);
379→
380→				// Close previous bridge's listener
381→				if (existing.detachCleanup) {
382→					existing.detachCleanup();
383→					existing.detachCleanup = undefined;
384→				}
385→
386→				this.session = existing.session;
387→				this.authStorage = existing.authStorage;
388→				this.resourceLoader = existing.resourceLoader as DefaultResourceLoader;
389→				this.sessionPool.touch(this.options.sessionId);
390→
391→				// Flush buffered output
392→				try {
393→					const bufferedLines = await this.outputBufferService.flushOrdered(this.options.sessionId);
394→					if (bufferedLines.length > 0) {
395→						console.log(`[sdk-bridge] Sending ${bufferedLines.length} buffered line(s)`);
396→						for (const line of bufferedLines) {
397→							try { this.ws.send(line); } catch {}
398→						}
399→					}
400→				} catch (err) {
401→					console.error("[sdk-bridge] Failed to flush output buffer:", err);
402→				}
403→
404→				// Notify client of reattachment
405→				try {
406→					this.ws.send(JSON.stringify({ type: "session_reattached", sessionId: this.options.sessionId }));
407→				} catch {}
408→
409→				// Subscribe to events and forward to WS
410→				this.subscribeToSession();
411→				this.detached = false;
412→				this.ready = true;
413→				this.flushPendingMessages();
414→
415→				// Register owner for SSE fan-out
416→				this.sessionStatusService.registerOwner(this.options.sessionId, this.user.userId);
417→				return;
418→			} else if (existing) {
419→				console.warn(`[sdk-bridge] User ${this.user.userId} tried to reattach to session owned by ${existing.userId}`);
420→			}
421→		}
422→
423→		// Defer session creation until first user message (lazy spawn)
424→		this.ready = true;
425→
426→		// Flush any messages that arrived during startAsync() through the
427→		// normal dispatch path (handles get_state, lazy creation, etc.)
428→		if (this.pendingMessages.length > 0) {
429→			const buffered = this.pendingMessages;
430→			this.pendingMessages = [];
431→			for (const { parsed } of buffered) {
432→				this.dispatchCommand(parsed);
433→			}
434→		}
435→
436→		try {
437→			this.ws.send(JSON.stringify({ type: "bridge_ready", sessionId: this.sessionId }));
438→		} catch {}
439→	}
440→
441→	/**
442→	 * Lazily create the AgentSession on first user message.
443→	 */
444→	private async createSessionLazy(): Promise<void> {
445→		if (this.session || this.sessionCreating) return;
446→		this.sessionCreating = true;
447→
448→		const modelRegistry = new ModelRegistry(this.authStorage!);
449→
450→		// Resolve the model — prefer user's explicit choice over DB fallback
451→		let model = undefined;
452→		const modelId = this.options.model && this.options.model !== "loading..."
453→			? this.options.model
454→			: this.sessionModel?.id ?? undefined;
455→		const provider = this.options.provider || this.sessionModel?.provider || undefined;
456→
457→		if (modelId && provider) {
458→			model = modelRegistry.find(provider, modelId);
459→			if (!model) {
460→				console.warn(`[sdk-bridge] Model ${provider}/${modelId} not found in registry, using default`);
461→			}
462→		}
463→
464→		// If no model resolved, pick best default from preferred list, then configured providers
465→		if (!model) {
466→			const available = modelRegistry.getAvailable();
467→			model = pickDefaultModel(available, this.configuredProviders);
468→		}
469→
470→		const { session, extensionsResult } = await createAgentSession({
471→			cwd: this.options.cwd || process.cwd(),
472→			authStorage: this.authStorage!,
473→			modelRegistry,
474→			model,
475→			resourceLoader: this.resourceLoader!,
476→			sessionManager: SessionManager.inMemory(this.options.cwd || process.cwd()),
477→			settingsManager: SettingsManager.inMemory(),
478→		});
479→
480→		this.session = session;
481→
482→		// Bind extensions with a UI context that forwards to WS
483→		await session.bindExtensions({
484→			uiContext: this.createUIContext(),
485→			commandContextActions: this.createCommandContextActions(),
486→			shutdownHandler: () => {
487→				console.log("[sdk-bridge] Extension requested shutdown");
488→				this.stop();
489→			},
490→			onError: (err) => {
491→				console.error("[sdk-bridge] Extension error:", err);
492→			},
493→		});
494→
495→		// Store in session pool
496→		this.sessionPool.acquire({
497→			sessionId: this.sessionId,
498→			userId: this.user.userId,
