337→	private async handleConnect(provider: string) {
338→		this.connecting = { ...this.connecting, [provider]: true };
339→		this.statusMessage = "";
340→
341→		try {
342→			// Start OAuth flow
343→			const startResult = await this.fetchApi(`/api/oauth/${provider}/start`, {
344→				method: "POST",
345→			});
346→
347→			if (!startResult.success) {
348→				this.statusMessage = startResult.error || "Failed to start OAuth flow";
349→				this.statusType = "error";
350→				this.connecting = { ...this.connecting, [provider]: false };
351→				return;
352→			}
353→
354→			const { authUrl, state } = startResult.data;
355→
356→			// Open OAuth URL in popup
357→			const popup = window.open(
358→				authUrl,
359→				"oauth_popup",
360→				"width=600,height=700,left=100,top=100"
361→			);
362→
363→			if (!popup) {
364→				this.statusMessage = "Please allow popups to connect";
365→				this.statusType = "error";
366→				this.connecting = { ...this.connecting, [provider]: false };
367→				return;
368→			}
369→
370→			// Store state and show inline code input
371→			this.oauthPopup = popup;
372→			this.pendingState = state;
373→			this.pendingCodeProvider = provider;
374→			this.showPasteFallback = false;
375→
376→			// For providers using localhost redirects, show fallback paste
377→			// instructions after a delay in case postMessage doesn't work (cloud)
378→			if (this.fallbackTimer) clearTimeout(this.fallbackTimer);
379→			if (provider !== "anthropic") {
380→				this.fallbackTimer = setTimeout(() => {
381→					if (this.pendingCodeProvider) {
382→						this.showPasteFallback = true;
383→					}
384→				}, 5000);
385→			}
386→		} catch (err) {
387→			console.error("OAuth connection error:", err);
388→			this.statusMessage = "Network error";
389→			this.statusType = "error";
390→			this.connecting = { ...this.connecting, [provider]: false };
391→		}
392→	}
393→
394→	private async handleCodeSubmit() {
395→		const provider = this.pendingCodeProvider;
396→		const state = this.pendingState;
397→		if (!provider || !state) return;
398→
399→		const input = this.shadowRoot?.querySelector<HTMLInputElement>("#oauth-code-input");
400→		const rawValue = input?.value?.trim();
401→		if (!rawValue) return;
402→
403→		// Parse input: accept a full redirect URL, "code#state" format, or bare code
404→		let code: string;
405→		try {
406→			const url = new URL(rawValue);
407→			code = url.searchParams.get("code") || rawValue;
408→		} catch {
409→			code = rawValue.split("#")[0];
410→		}
411→
412→		// Close popup if still open
413→		if (this.oauthPopup && !this.oauthPopup.closed) {
414→			this.oauthPopup.close();
415→		}
416→
417→		// Clear the pending state
418→		this.pendingCodeProvider = null;
419→		this.pendingState = null;
420→		this.oauthPopup = null;
421→
422→		try {
423→			const callbackResult = await this.fetchApi(`/api/oauth/${provider}/callback`, {
424→				method: "POST",
425→				body: JSON.stringify({ code, state }),
426→			});
427→
428→			if (callbackResult.success) {
429→				this.statusMessage = `Successfully connected ${PROVIDER_LABELS[provider]}`;
430→				this.statusType = "success";
431→				await this.loadConnections();
432→			} else {
433→				this.statusMessage = callbackResult.error || "Failed to complete OAuth flow";
434→				this.statusType = "error";
435→			}
436→		} catch (err) {
437→			console.error("OAuth connection error:", err);
438→			this.statusMessage = "Network error";
439→			this.statusType = "error";
440→		} finally {
441→			this.connecting = { ...this.connecting, [provider]: false };
442→		}
443→	}
444→
445→	private handleCodeCancel() {
446→		const provider = this.pendingCodeProvider;
447→		if (this.fallbackTimer) { clearTimeout(this.fallbackTimer); this.fallbackTimer = null; }
448→		this.showPasteFallback = false;
449→		if (this.oauthPopup && !this.oauthPopup.closed) {
450→			this.oauthPopup.close();
451→		}
452→		this.pendingCodeProvider = null;
453→		this.pendingState = null;
454→		this.oauthPopup = null;
455→		if (provider) {
456→			this.connecting = { ...this.connecting, [provider]: false };
457→		}
458→	}
459→
460→	private async handleDisconnect(provider: string) {
461→		if (!confirm(`Disconnect ${PROVIDER_LABELS[provider] || provider}?`)) return;
462→
463→		try {
464→			const result = await this.fetchApi(`/api/oauth/${provider}`, {
465→				method: "DELETE",
466→			});
467→
468→			if (result.success) {
469→				this.statusMessage = `Disconnected ${PROVIDER_LABELS[provider]}`;
470→				this.statusType = "success";
471→				await this.loadConnections();
472→			} else {
473→				this.statusMessage = result.error || "Failed to disconnect";
474→				this.statusType = "error";
475→			}
476→		} catch {
477→			this.statusMessage = "Network error";
478→			this.statusType = "error";
479→		}
480→	}
481→
482→	private get connectedProviders(): Set<string> {
483→		return new Set(this.connections.map((c) => c.provider));
484→	}
