  1→/**
  2→ * AgentExecutor: shared logic for spawning pi --mode rpc processes.
  3→ *
  4→ * Used by SdkBridge (chat), SchedulerWorker (cron jobs), and TaskQueueService
  5→ * (background tasks). Consolidates provider key resolution, OAuth credential
  6→ * injection, skill resolution, file download, and process spawning.
  7→ */
  8→
  9→import { type ChildProcess, spawn } from "node:child_process";
 10→import * as fs from "node:fs/promises";
 11→import * as os from "node:os";
 12→import * as path from "node:path";
 13→import { fileURLToPath } from "node:url";
 14→import { resolvePiCommand } from "../utils/resolve-command.js";
 15→import { PROVIDER_ENV_MAP, OAUTH_PROVIDER_ENV_MAP, PROVIDER_CONFIG_ENV_MAP } from "../utils/provider-env-map.js";
 16→import type { Database, ProviderKeyRow, UserFileRow } from "../db/types.js";
 17→import type { CryptoService } from "./crypto.js";
 18→import type { StorageService } from "./storage.js";
 19→import { OAuthService } from "./oauth-service.js";
 20→import { resolveSkillsForUser, type ResolvedSkills } from "./skill-resolver.js";
 21→
 22→export interface SpawnOptions {
 23→	userId: string;
 24→	teamId: string;
 25→	provider?: string;
 26→	model?: string;
 27→	skillIds?: string[];
 28→	fileIds?: string[];
