 42→export class AgentExecutor {
 43→	private db: Database;
 44→	private crypto: CryptoService;
 45→	private storage: StorageService;
 46→
 47→	constructor(deps: { db: Database; crypto: CryptoService; storage: StorageService }) {
 48→		this.db = deps.db;
 49→		this.crypto = deps.crypto;
 50→		this.storage = deps.storage;
 51→	}
 52→
 53→	/**
 54→	 * Build environment variables with team provider keys + user OAuth overrides.
 55→	 */
 56→	async buildEnv(userId: string, teamId: string): Promise<Record<string, string>> {
 57→		const env: Record<string, string> = {};
 58→
 59→		// Team-level provider keys
 60→		const keyResult = await this.db.query<ProviderKeyRow>(
 61→			`SELECT provider, encrypted_dek, encrypted_key, iv, key_version, config FROM provider_keys WHERE team_id = $1`,
 62→			[teamId],
 63→		);
 64→
 65→		for (const row of keyResult.rows) {
 66→			try {
 67→				const apiKey = this.crypto.decrypt({
 68→					encryptedDek: row.encrypted_dek,
 69→					encryptedData: row.encrypted_key,
 70→					iv: row.iv,
 71→					keyVersion: row.key_version,
 72→				});
 73→				const envVar = PROVIDER_ENV_MAP[row.provider] || `${row.provider.toUpperCase().replace(/-/g, "_")}_API_KEY`;
 74→				env[envVar] = apiKey;
 75→
 76→				// Inject provider-specific config as env vars
 77→				const configMap = PROVIDER_CONFIG_ENV_MAP[row.provider];
 78→				if (configMap && row.config) {
 79→					for (const [field, envName] of Object.entries(configMap)) {
 80→						let value = row.config[field];
 81→						if (value === undefined || value === null || value === "") continue;
 82→
 83→						// Azure base URL needs /openai/v1 suffix for the AzureOpenAI SDK
 84→						if (field === "baseUrl" && row.provider === "azure-openai") {
 85→							let url = String(value).replace(/\/+$/, "");
 86→							if (!url.endsWith("/openai/v1")) {
 87→								url += "/openai/v1";
 88→							}
 89→							value = url;
 90→						}
 91→
 92→						env[envName] = String(value);
 93→					}
 94→				}
 95→			} catch (err) {
 96→				console.error(`[agent-executor] Failed to decrypt key for provider ${row.provider}:`, err);
 97→			}
 98→		}
 99→
100→		// OAuth credentials (override team keys) — batch all providers in parallel
101→		const oauthService = new OAuthService(this.db.pool, this.crypto);
102→		const oauthEntries = Object.entries(OAUTH_PROVIDER_ENV_MAP);
103→		const oauthResults = await Promise.allSettled(
104→			oauthEntries.map(([providerId]) => oauthService.getApiKey(providerId as any, { userId })),
105→		);
106→		for (let i = 0; i < oauthEntries.length; i++) {
107→			const result = oauthResults[i];
108→			if (result.status === "fulfilled" && result.value) {
109→				env[oauthEntries[i][1]] = result.value;
110→			}
111→		}
112→
113→		return env;
114→	}
115→
116→	/**
117→	 * Download file_ids to targetDir, return absolute paths.
118→	 */
119→	async downloadFiles(fileIds: string[], targetDir: string): Promise<string[]> {
120→		const fileResult = await this.db.query<UserFileRow>(
121→			`SELECT id, filename, storage_key FROM user_files WHERE id = ANY($1)`,
122→			[fileIds],
123→		);
124→
125→		const paths = await Promise.all(
126→			fileResult.rows.map(async (file) => {
127→				const filePath = path.join(targetDir, file.filename);
128→				// Path traversal protection: ensure resolved path stays within target directory
129→				const resolved = path.resolve(filePath);
130→				if (!resolved.startsWith(path.resolve(targetDir) + path.sep)) {
131→					throw new Error(`Filename escapes target directory: ${file.filename}`);
132→				}
133→				const data = await this.storage.download(file.storage_key);
134→				await fs.writeFile(filePath, data);
135→				return filePath;
136→			}),
137→		);
138→		return paths;
139→	}
140→
141→	/**
142→	 * Full spawn: resolve keys + skills + files → spawn pi --mode rpc.
143→	 */
144→	async spawn(opts: SpawnOptions): Promise<SpawnResult> {
145→		// Run independent prep steps in parallel
146→		const [extraEnv, resolvedSkills, { tempFilesDir, filePaths }] = await Promise.all([
147→			// 1. Build environment
148→			this.buildEnv(opts.userId, opts.teamId),
149→			// 2. Resolve skills
150→			resolveSkillsForUser(this.db, this.storage, opts.userId, opts.teamId),
151→			// 3. Download files if needed
152→			(async () => {
153→				if (opts.fileIds && opts.fileIds.length > 0) {
154→					const dir = await fs.mkdtemp(path.join(os.tmpdir(), "pi-task-files-"));
155→					const paths = await this.downloadFiles(opts.fileIds, dir);
156→					return { tempFilesDir: dir, filePaths: paths };
157→				}
158→				return { tempFilesDir: null as string | null, filePaths: [] as string[] };
159→			})(),
160→		]);
161→
162→		// 4. Build command args
163→		const { command, commandArgs } = resolvePiCommand();
164→		const args = [...commandArgs, "--mode", "rpc"];
165→		if (opts.provider) args.push("--provider", opts.provider);
166→		if (opts.model) args.push("--model", opts.model);
167→		if (opts.extraArgs) args.push(...opts.extraArgs);
168→
169→		for (const skillPath of resolvedSkills.skillPaths) {
170→			args.push("--skill", skillPath);
171→		}
172→		for (const filePath of filePaths) {
173→			args.push("--file", filePath);
174→		}
175→
176→		// Inject Brave Search extension
177→		if (opts.injectBraveSearch !== false && process.env.BRAVE_SEARCH_API_KEY) {
178→			const braveSearchExt = fileURLToPath(new URL("../extensions/brave-search.ts", import.meta.url));
179→			args.push("--extension", braveSearchExt);
180→		}
181→
182→		console.log(`[agent-executor] Spawning: ${command} ${args.join(" ")}`);
183→
184→		// 5. Spawn
185→		const child = spawn(command, args, {
186→			cwd: opts.cwd || process.cwd(),
187→			env: { ...process.env, ...extraEnv },
188→			stdio: ["pipe", "pipe", "pipe"],
189→		});
190→
191→		const cleanup = async () => {
192→			resolvedSkills.cleanup();
193→			if (tempFilesDir) {
194→				await fs.rm(tempFilesDir, { recursive: true, force: true }).catch(() => {});
195→			}
196→		};
197→
198→		return { process: child, resolvedSkills, tempFilesDir, filePaths, cleanup };
199→	}
200→}
