267→	/** Handle postMessage from OAuth callback page */
268→	private handleOAuthMessage(e: MessageEvent) {
269→		if (!e.data || e.data.type !== "oauth-callback") return;
270→		const { code, state } = e.data;
271→		if (!code || !state) return;
272→		// Verify this matches our pending flow
273→		if (state !== this.pendingState) return;
274→
275→		// Auto-complete the flow
276→		this.completeOAuthExchange(code, state);
277→	}
278→
279→	/** Complete token exchange with the server */
280→	private async completeOAuthExchange(code: string, state: string) {
281→		const provider = this.pendingCodeProvider;
282→		if (!provider) return;
283→
284→		// Clear timers
285→		if (this.fallbackTimer) { clearTimeout(this.fallbackTimer); this.fallbackTimer = null; }
286→		this.showPasteFallback = false;
287→
288→		// Close popup if still open
289→		if (this.oauthPopup && !this.oauthPopup.closed) {
290→			this.oauthPopup.close();
291→		}
292→
293→		// Clear pending state
294→		this.pendingCodeProvider = null;
295→		this.pendingState = null;
296→		this.oauthPopup = null;
297→
298→		try {
299→			const callbackResult = await this.fetchApi(`/api/oauth/${provider}/callback`, {
300→				method: "POST",
301→				body: JSON.stringify({ code, state }),
302→			});
303→
304→			if (callbackResult.success) {
305→				this.statusMessage = `Successfully connected ${PROVIDER_LABELS[provider]}`;
306→				this.statusType = "success";
307→				await this.loadConnections();
308→			} else {
309→				this.statusMessage = callbackResult.error || "Failed to complete OAuth flow";
310→				this.statusType = "error";
311→			}
312→		} catch (err) {
313→			console.error("OAuth connection error:", err);
314→			this.statusMessage = "Network error";
315→			this.statusType = "error";
316→		} finally {
317→			this.connecting = { ...this.connecting, [provider]: false };
318→		}
319→	}
320→
321→	private fetchApi = (url: string, options?: RequestInit) => apiFetch(url, options, this.getToken);
322→
323→	private async loadConnections() {
324→		this.loading = true;
325→		try {
326→			const result = await this.fetchApi("/api/oauth");
327→			if (result.success) {
328→				this.connections = result.data.credentials;
329→			}
330→		} catch (err) {
331→			console.error("Failed to load OAuth connections:", err);
332→		} finally {
333→			this.loading = false;
334→		}
335→	}
