 1→/**
 2→ * Generates sendRuntimeMessage() function for injection into execution contexts.
 3→ * Provides unified messaging API that works in both sandbox iframe and user script contexts.
 4→ */
 5→
 6→export type MessageType = "request-response" | "fire-and-forget";
 7→
 8→export interface RuntimeMessageBridgeOptions {
 9→	context: "sandbox-iframe" | "user-script";
10→	sandboxId: string;
11→}
12→
13→// biome-ignore lint/complexity/noStaticOnlyClass: fine
14→export class RuntimeMessageBridge {
15→	/**
16→	 * Generate sendRuntimeMessage() function as injectable string.
17→	 * Returns the function source code to be injected into target context.
18→	 */
19→	static generateBridgeCode(options: RuntimeMessageBridgeOptions): string {
20→		if (options.context === "sandbox-iframe") {
21→			return RuntimeMessageBridge.generateSandboxBridge(options.sandboxId);
22→		} else {
23→			return RuntimeMessageBridge.generateUserScriptBridge(options.sandboxId);
24→		}
25→	}
26→
27→	private static generateSandboxBridge(sandboxId: string): string {
28→		// Returns stringified function that uses window.parent.postMessage
29→		return `
30→window.__completionCallbacks = [];
31→window.sendRuntimeMessage = async (message) => {
32→    const messageId = 'msg_' + Date.now() + '_' + Math.random().toString(36).substring(2, 9);
33→
34→    return new Promise((resolve, reject) => {
35→        const handler = (e) => {
36→            if (e.data.type === 'runtime-response' && e.data.messageId === messageId) {
37→                window.removeEventListener('message', handler);
38→                if (e.data.success) {
39→                    resolve(e.data);
40→                } else {
41→                    reject(new Error(e.data.error || 'Operation failed'));
42→                }
43→            }
44→        };
45→
46→        window.addEventListener('message', handler);
47→
48→        window.parent.postMessage({
49→            ...message,
50→            sandboxId: ${JSON.stringify(sandboxId)},
51→            messageId: messageId
52→        }, '*');
53→
54→        // Timeout after 30s
55→        setTimeout(() => {
56→            window.removeEventListener('message', handler);
57→            reject(new Error('Runtime message timeout'));
58→        }, 30000);
59→    });
60→};
61→window.onCompleted = (callback) => {
62→    window.__completionCallbacks.push(callback);
63→};
64→`.trim();
65→	}
66→
67→	private static generateUserScriptBridge(sandboxId: string): string {
68→		// Returns stringified function that uses chrome.runtime.sendMessage
69→		return `
70→window.__completionCallbacks = [];
71→window.sendRuntimeMessage = async (message) => {
72→    return await chrome.runtime.sendMessage({
73→        ...message,
74→        sandboxId: ${JSON.stringify(sandboxId)}
75→    });
76→};
77→window.onCompleted = (callback) => {
78→    window.__completionCallbacks.push(callback);
79→};
80→`.trim();
81→	}
82→}
