  6→/**
  7→ * Message consumer interface - components that want to receive messages from sandboxes
  8→ */
  9→export interface MessageConsumer {
 10→	/**
 11→	 * Handle a message from a sandbox.
 12→	 * All consumers receive all messages - decide internally what to handle.
 13→	 */
 14→	handleMessage(message: any): Promise<void>;
 15→}
 16→
 17→/**
 18→ * Sandbox context - tracks active sandboxes and their consumers
 19→ */
 20→interface SandboxContext {
 21→	sandboxId: string;
 22→	iframe: HTMLIFrameElement | null; // null until setSandboxIframe() or null for user scripts
 23→	providers: SandboxRuntimeProvider[];
 24→	consumers: Set<MessageConsumer>;
 25→}
 26→
 27→/**
 28→ * Centralized message router for all runtime communication.
 29→ *
 30→ * This singleton replaces all individual window.addEventListener("message") calls
 31→ * with a single global listener that routes messages to the appropriate handlers.
 32→ * Also handles user script messages from chrome.runtime.onUserScriptMessage.
 33→ *
 34→ * Benefits:
 35→ * - Single global listener instead of multiple independent listeners
 36→ * - Automatic cleanup when sandboxes are destroyed
 37→ * - Support for bidirectional communication (providers) and broadcasting (consumers)
 38→ * - Works with both sandbox iframes and user scripts
 39→ * - Clear lifecycle management
 40→ */
 41→export class RuntimeMessageRouter {
 42→	private sandboxes = new Map<string, SandboxContext>();
 43→	private messageListener: ((e: MessageEvent) => void) | null = null;
 44→	private userScriptMessageListener:
 45→		| ((message: any, sender: any, sendResponse: (response: any) => void) => boolean)
 46→		| null = null;
 47→
 48→	/**
 49→	 * Register a new sandbox with its runtime providers.
 50→	 * Call this BEFORE creating the iframe (for sandbox contexts) or executing user script.
 51→	 */
 52→	registerSandbox(sandboxId: string, providers: SandboxRuntimeProvider[], consumers: MessageConsumer[]): void {
 53→		this.sandboxes.set(sandboxId, {
 54→			sandboxId,
 55→			iframe: null, // Will be set via setSandboxIframe() for sandbox contexts
 56→			providers,
 57→			consumers: new Set(consumers),
 58→		});
 59→
 60→		// Setup global listener if not already done
 61→		this.setupListener();
 62→	}
 63→
 64→	/**
 65→	 * Update the iframe reference for a sandbox.
 66→	 * Call this AFTER creating the iframe.
 67→	 * This is needed so providers can send responses back to the sandbox.
 68→	 */
 69→	setSandboxIframe(sandboxId: string, iframe: HTMLIFrameElement): void {
 70→		const context = this.sandboxes.get(sandboxId);
 71→		if (context) {
 72→			context.iframe = iframe;
 73→		}
 74→	}
 75→
 76→	/**
 77→	 * Unregister a sandbox and remove all its consumers.
 78→	 * Call this when the sandbox is destroyed.
 79→	 */
 80→	unregisterSandbox(sandboxId: string): void {
 81→		this.sandboxes.delete(sandboxId);
 82→
 83→		// If no more sandboxes, remove global listeners
 84→		if (this.sandboxes.size === 0) {
 85→			// Remove iframe listener
 86→			if (this.messageListener) {
 87→				window.removeEventListener("message", this.messageListener);
 88→				this.messageListener = null;
 89→			}
 90→
 91→			// Remove user script listener
 92→			if (this.userScriptMessageListener && typeof chrome !== "undefined" && chrome.runtime?.onUserScriptMessage) {
 93→				chrome.runtime.onUserScriptMessage.removeListener(this.userScriptMessageListener);
 94→				this.userScriptMessageListener = null;
 95→			}
 96→		}
 97→	}
 98→
 99→	/**
100→	 * Add a message consumer for a sandbox.
101→	 * Consumers receive broadcast messages (console, execution-complete, etc.)
102→	 */
103→	addConsumer(sandboxId: string, consumer: MessageConsumer): void {
104→		const context = this.sandboxes.get(sandboxId);
105→		if (context) {
106→			context.consumers.add(consumer);
107→		}
108→	}
109→
110→	/**
111→	 * Remove a message consumer from a sandbox.
112→	 */
113→	removeConsumer(sandboxId: string, consumer: MessageConsumer): void {
114→		const context = this.sandboxes.get(sandboxId);
115→		if (context) {
116→			context.consumers.delete(consumer);
117→		}
118→	}
119→
120→	/**
121→	 * Setup the global message listeners (called automatically)
122→	 */
123→	private setupListener(): void {
124→		// Setup sandbox iframe listener
125→		if (!this.messageListener) {
126→			this.messageListener = async (e: MessageEvent) => {
127→				const { sandboxId, messageId } = e.data;
128→				if (!sandboxId) return;
129→
130→				const context = this.sandboxes.get(sandboxId);
131→				if (!context) {
132→					return;
133→				}
134→
135→				// Create respond() function for bidirectional communication
136→				const respond = (response: any) => {
137→					context.iframe?.contentWindow?.postMessage(
138→						{
139→							type: "runtime-response",
140→							messageId,
141→							sandboxId,
142→							...response,
143→						},
144→						"*",
145→					);
146→				};
147→
148→				// 1. Try provider handlers first (for bidirectional comm)
149→				for (const provider of context.providers) {
150→					if (provider.handleMessage) {
151→						await provider.handleMessage(e.data, respond);
152→						// Don't stop - let consumers also handle the message
153→					}
154→				}
155→
156→				// 2. Broadcast to consumers (one-way messages or lifecycle events)
157→				for (const consumer of context.consumers) {
158→					await consumer.handleMessage(e.data);
159→					// Don't stop - let all consumers see the message
160→				}
161→			};
162→
163→			window.addEventListener("message", this.messageListener);
164→		}
165→
166→		// Setup user script message listener
167→		if (!this.userScriptMessageListener) {
168→			// Guard: check if we're in extension context
169→			if (typeof chrome === "undefined" || !chrome.runtime?.onUserScriptMessage) {
170→				return;
171→			}
172→
173→			this.userScriptMessageListener = (message: any, _sender: any, sendResponse: (response: any) => void) => {
174→				const { sandboxId } = message;
175→				if (!sandboxId) return false;
176→
177→				const context = this.sandboxes.get(sandboxId);
178→				if (!context) return false;
179→
180→				const respond = (response: any) => {
181→					sendResponse({
182→						...response,
183→						sandboxId,
184→					});
185→				};
186→
187→				// Route to providers (async)
188→				(async () => {
189→					// 1. Try provider handlers first (for bidirectional comm)
190→					for (const provider of context.providers) {
191→						if (provider.handleMessage) {
192→							await provider.handleMessage(message, respond);
193→							// Don't stop - let consumers also handle the message
194→						}
195→					}
196→
197→					// 2. Broadcast to consumers (one-way messages or lifecycle events)
198→					for (const consumer of context.consumers) {
199→						await consumer.handleMessage(message);
200→						// Don't stop - let all consumers see the message
201→					}
202→				})();
203→
204→				return true; // Indicates async response
205→			};
206→
207→			chrome.runtime.onUserScriptMessage.addListener(this.userScriptMessageListener);
208→		}
209→	}
210→}
