234→	app.get("/healthz", (_req, res) => {
235→		res.json({ status: "ok" });
236→	});
237→	// Detailed health (behind auth) with pool/queue stats
238→	app.get("/healthz/details", requireAuth, (_req, res) => {
239→		res.json({
240→			status: "ok",
241→			sessionPool: sessionPool.stats(),
242→			taskQueue: taskQueueService.stats(),
243→		});
244→	});
245→
246→	// 1.7 WebSocket per-user connection tracking
247→	const wsConnectionCounts = new Map<string, number>();
248→	const WS_MAX_PER_USER = 5;
249→
250→	// Track active CWDs per user (for agent-files endpoint)
251→	const activeUserCwds = new Map<string, string>();
252→
253→	// --- OAuth callback page (also served on port 1455 below) ---
254→	// Kept on the main Express server for cloud deployments with custom OAuth clients.
255→	app.get("/auth/openai-callback", apiRateLimit, oauthCallbackHandler);
256→
257→	// --- API Routes ---
258→	app.use("/api/auth", authRateLimit, authRouter);
259→	app.use("/api/sessions", apiRateLimit, createSessionsRouter(sessionStatusService, sessionPool));
260→	app.use("/api/settings", requireAuth, apiRateLimit, settingsRouter);
261→	app.use("/api/import", requireAuth, apiRateLimit, importRouter);
262→	app.use("/api/provider-keys", apiRateLimit, createProviderKeysRouter(crypto));
263→	app.use("/api/skills", apiRateLimit, createSkillsRouter(storageService));
264→	app.use("/api/files", apiRateLimit, createFilesRouter(storageService));
265→	app.use("/api/oauth", apiRateLimit, createOAuthRouter(crypto));
266→	app.use("/api/jobs", apiRateLimit, createJobsRouter(storageService, crypto));
267→	app.use("/api/tasks", apiRateLimit, createTasksRouter(storageService, crypto, taskQueueService));
268→	app.use("/api/agent-profiles", apiRateLimit, createAgentProfilesRouter(agentExecutor));
269→	app.use("/api/memory", apiRateLimit, createMemoryRouter());
270→	app.use("/api/team-members", apiRateLimit, createTeamMembersRouter());
271→	app.use("/api/projects", apiRateLimit, createProjectsRouter(agentExecutor));
272→	app.use("/api/invites", apiRateLimit, createInvitesRouter());
273→
274→	// Read files from the agent's working directory (for rendering artifacts)
275→	app.get("/api/agent-files", requireAuth, apiRateLimit, async (req, res) => {
276→		const rawPath = req.query.path as string;
277→		if (!rawPath) {
278→			return res.status(400).json({ error: "Path required" });
279→		}
280→		// Resolve relative paths against the user's active CWD
281→		const userId = (req as any).user?.userId;
282→		const cwd = activeUserCwds.get(userId);
283→		let filePath: string;
284→		if (path.isAbsolute(rawPath)) {
285→			filePath = rawPath;
286→		} else if (cwd) {
287→			filePath = path.resolve(cwd, rawPath);
288→		} else {
289→			return res.status(400).json({ error: "Absolute path required (no active CWD)" });
290→		}
291→		// Only allow renderable file types
292→		const ext = path.extname(filePath).slice(1).toLowerCase();
293→		if (!RENDERABLE_EXTENSIONS.has(ext)) {
294→			return res.status(400).json({ error: "Unsupported file type" });
295→		}
296→		// 1.8 Path traversal fix: resolve symlinks and use path.sep to prevent prefix attacks.
297→		// Allow temp directory files — agents commonly generate outputs there (python-pptx, etc.).
298→		if (cwd) {
299→			try {
300→				const realFile = await fs.realpath(filePath);
301→				const realCwd = await fs.realpath(cwd);
302→				const inTempDir =
303→					realFile.startsWith("/tmp/") ||
304→					realFile.startsWith("/private/tmp/"); // macOS: /tmp → /private/tmp
305→				if (
306→					!inTempDir &&
307→					!realFile.startsWith(realCwd + path.sep) &&
308→					realFile !== realCwd
309→				) {
310→					return res.status(403).json({ error: "Path is outside working directory" });
311→				}
312→				filePath = realFile;
313→			} catch {
314→				return res.status(404).json({ error: "File not found" });
315→			}
316→		}
317→		try {
318→			// PPTX: convert to slide images server-side via LibreOffice
319→			if (ext === "pptx" || ext === "ppt") {
320→				try {
321→					const { convertPptxToSlideImages } = await import("./services/pptx-converter.js");
322→					const [slides, rawBuffer] = await Promise.all([
323→						convertPptxToSlideImages(filePath),
324→						fs.readFile(filePath),
325→					]);
326→					res.json({ slides, raw: rawBuffer.toString("base64"), encoding: "slides" });
327→					return;
328→				} catch (convErr: any) {
329→					// LibreOffice/pdftoppm not installed — fall back to raw base64
330→					console.warn("[agent-files] PPTX conversion failed, serving raw binary:", convErr.message);
331→					const buffer = await fs.readFile(filePath);
332→					res.json({ content: buffer.toString("base64"), encoding: "base64" });
333→					return;
334→				}
335→			}
336→
337→			const isBinary = BINARY_EXTENSIONS.has(ext);
338→			if (isBinary) {
339→				const buffer = await fs.readFile(filePath);
340→				const base64Content = buffer.toString("base64");
341→				res.json({ content: base64Content, encoding: "base64" });
342→			} else {
343→				const content = await fs.readFile(filePath, "utf-8");
344→				res.json({ content, encoding: "text" });
345→			}
346→		} catch (err: any) {
347→			console.error("[agent-files] Error serving file:", err.message);
348→			res.status(404).json({ error: "File not found" });
349→		}
350→	});
351→
352→	// --- WebSocket ---
353→	const server = createServer(app);
354→	const wss = new WebSocketServer({ noServer: true, maxPayload: 10 * 1024 * 1024 });
355→
356→	wss.on("connection", async (ws, req) => {
357→		// Auth user is attached by the upgrade handler
358→		const user = (req as any).__authUser;
359→		console.log(`[server] New WebSocket connection from ${user?.email || "unknown"}`);
360→
361→		// 1.7 Enforce per-user WebSocket connection limit
362→		if (user?.userId) {
363→			const count = wsConnectionCounts.get(user.userId) || 0;
364→			if (count >= WS_MAX_PER_USER) {
365→				console.warn(`[server] WebSocket limit exceeded for ${user.email} (${count}/${WS_MAX_PER_USER})`);
366→				ws.close(4029, "Too many connections");
367→				return;
368→			}
369→			wsConnectionCounts.set(user.userId, count + 1);
370→			ws.on("close", () => {
371→				const current = wsConnectionCounts.get(user.userId) || 1;
372→				if (current <= 1) {
373→					wsConnectionCounts.delete(user.userId);
374→				} else {
375→					wsConnectionCounts.set(user.userId, current - 1);
376→				}
377→			});
378→		}
379→
380→		// Buffer messages that arrive before the bridge's message handler is
381→		// registered. The async DB queries below (session ownership, profile
382→		// resolution) can take long enough for the client's first message
383→		// (get_state) to arrive and be silently dropped.
384→		const earlyMessages: Buffer[] = [];
385→		const earlyHandler = (data: Buffer) => earlyMessages.push(data);
386→		ws.on("message", earlyHandler);
387→
388→		// Parse bridge options from query params
389→		const url = new URL(req.url || "/", `http://localhost:${PORT}`);
390→		const options: BridgeOptions = {};
391→		if (url.searchParams.has("cwd")) options.cwd = url.searchParams.get("cwd")!;
392→		if (url.searchParams.has("provider")) options.provider = url.searchParams.get("provider")!;
393→		if (url.searchParams.has("model")) options.model = url.searchParams.get("model")!;
394→
395→		let sessionId = url.searchParams.get("sessionId") || undefined;
396→
397→		// Validate session ownership before allowing reconnection
398→		if (sessionId) {
399→			const sessionResult = await db.query<{ user_id: string }>(
400→				"SELECT user_id FROM sessions WHERE id = $1 AND deleted_at IS NULL",
401→				[sessionId],
402→			);
403→			if (sessionResult.rows.length === 0) {
404→				// Session not in DB yet (async client save may be in-flight).
405→				// Keep sessionId so SdkBridge can check the session pool for
406→				// reattachment. Pool-level userId check prevents cross-user access.
407→			} else if (sessionResult.rows[0].user_id !== user.userId) {
408→				console.warn(`[server] User ${user.userId} attempted to access session ${sessionId} owned by ${sessionResult.rows[0].user_id}`);
409→				ws.close(4003, "Session not owned by authenticated user");
410→				return;
411→			}
412→		}
413→
414→		// Track CWD for agent-files endpoint (use explicit cwd or fall back to server CWD)
415→		activeUserCwds.set(user.userId, options.cwd || process.cwd());
416→
417→		// Resolve agent profile if specified
418→		const agentProfileId = url.searchParams.get("agentProfileId") || undefined;
419→		let profileSkillIds: string[] | undefined;
420→		let profileFileIds: string[] | undefined;
421→
422→		if (agentProfileId) {
423→			try {
424→				const profileResult = await db.query<AgentProfileRow>(
425→					`SELECT * FROM agent_profiles WHERE id = $1
426→					 AND ((scope = 'platform')
427→					   OR (scope = 'team' AND owner_id = $2)
428→					   OR (scope = 'user' AND owner_id = $3))`,
429→					[agentProfileId, user.teamId, user.userId],
430→				);
431→				const profile = profileResult.rows[0];
432→				if (profile) {
433→					// Profile fields applied as defaults (explicit query params override)
434→					if (!options.provider && profile.provider) options.provider = profile.provider;
435→					if (!options.model && profile.model_id) options.model = profile.model_id;
436→					// System prompt from profile
437→					if (profile.prompt_mode === "append") {
438→						options.appendSystemPrompt = profile.system_prompt;
439→					} else {
440→						options.systemPrompt = profile.system_prompt;
441→					}
442→					profileSkillIds = profile.skill_ids ?? undefined;
443→					profileFileIds = profile.file_ids ?? undefined;
444→					// Increment use count (fire-and-forget)
445→					db.query(
446→						`UPDATE agent_profiles SET use_count = use_count + 1 WHERE id = $1`,
447→						[agentProfileId],
448→					).catch(() => {});
449→					console.log(`[server] Using agent profile "${profile.name}" (${agentProfileId})`);
450→				} else {
451→					console.warn(`[server] Agent profile ${agentProfileId} not found or not accessible`);
452→				}
453→			} catch (err) {
454→				console.error("[server] Failed to resolve agent profile:", err);
455→			}
456→		}
457→
458→		// Create SDK bridge
459→		const sdkOptions: SdkBridgeOptions = {
460→			...options,
461→			user: {
462→				userId: user.userId,
463→				teamId: user.teamId,
464→				email: user.email,
465→				role: user.role,
466→			},
467→			sessionId,
468→			sessionPool,
469→			crypto,
470→			db,
471→			storage: storageService,
472→			sessionStatusService,
473→			outputBufferService,
474→			profileSkillIds,
475→			profileFileIds,
476→			agentProfileId,
477→			serverPort: PORT,
478→		};
479→		const bridge = new SdkBridge(ws, sdkOptions);
480→		bridge.start();
481→
482→		// Stop buffering — the bridge's message handler is now registered.
483→		// Replay any messages that arrived during the async setup above.
484→		ws.off("message", earlyHandler);
485→		for (const msg of earlyMessages) {
486→			ws.emit("message", msg);
487→		}
488→	});
489→
490→	// WebSocket upgrade handler with JWT authentication
491→	const handleUpgrade = (req: any, socket: any, head: any) => {
492→		const pathname = new URL(req.url || "/", `http://localhost:${PORT}`).pathname;
493→		if (pathname === "/ws") {
494→			// Authenticate WebSocket upgrade
495→			const user = authenticateWsUpgrade(req);
496→			if (!user) {
497→				socket.write("HTTP/1.1 401 Unauthorized\r\n\r\n");
498→				socket.destroy();
499→				return;
500→			}
501→
502→			// Attach user to request for the connection handler
503→			req.__authUser = user;
504→
505→			wss.handleUpgrade(req, socket, head, (ws) => {
506→				wss.emit("connection", ws, req);
507→			});
508→		} else if (isDev) {
509→			// In dev mode, let Vite handle non-/ws upgrades (HMR)
510→		} else {
511→			socket.destroy();
512→		}
513→	};
514→
515→	if (isDev) {
516→		// In dev mode, use Vite's dev server as middleware.
517→		const { createServer: createViteServer } = await import("vite");
518→		const vite = await createViteServer({
519→			configFile: path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../vite.config.ts"),
520→			root: path.resolve(path.dirname(fileURLToPath(import.meta.url)), ".."),
521→			server: {
522→				middlewareMode: true,
523→				hmr: {
524→					server,
525→				},
526→			},
527→		});
528→
529→		// Vite middleware AFTER API routes so /api/* is handled first
530→		app.use(vite.middlewares);
531→
532→		// Vite registers its own upgrade handler for HMR. We need a single
533→		// dispatcher that routes /ws to us and everything else to Vite.
534→		const viteUpgradeListeners = server.listeners("upgrade").slice();
535→		server.removeAllListeners("upgrade");
536→
537→		server.on("upgrade", (req: any, socket: any, head: any) => {
538→			const pathname = new URL(req.url || "/", `http://localhost:${PORT}`).pathname;
539→			if (pathname === "/ws") {
540→				handleUpgrade(req, socket, head);
541→			} else {
542→				// Forward to Vite's HMR upgrade handler(s)
543→				for (const listener of viteUpgradeListeners) {
544→					(listener as Function).call(server, req, socket, head);
545→				}
546→			}
547→		});
548→	} else {
549→		// In production, serve the built files
550→		const distPath = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../dist");
551→		app.use(express.static(distPath));
552→
553→		// SPA fallback — but not for /api/* routes
554→		app.get("/{*path}", (_req, res) => {
555→			res.sendFile(path.join(distPath, "index.html"));
556→		});
557→
558→		server.on("upgrade", handleUpgrade);
559→	}
560→
561→	// --- OAuth callback servers ---
562→	// Each OAuth provider has a fixed localhost redirect URI. We start lightweight
563→	// HTTP servers on the required ports to capture the redirect and relay the
564→	// authorization code to the opener window via postMessage.
565→	const oauthCallbackServers: Array<ReturnType<typeof createServer>> = [];
566→
567→	function startOAuthCallbackServer(port: number, path: string, envOverride?: string) {
568→		if (envOverride && process.env[envOverride]) return; // custom redirect, skip
569→		const srv = createServer((req, res) => {
570→			const url = new URL(req.url || "", `http://localhost:${port}`);
571→			if (url.pathname === path) {
572→				res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
573→				res.end(OAUTH_CALLBACK_HTML);
574→			} else {
575→				res.writeHead(404);
576→				res.end("Not found");
577→			}
578→		});
579→		srv.listen(port, "127.0.0.1", () => {
580→			console.log(`[server] OAuth callback on http://localhost:${port}${path}`);
581→		});
582→		srv.on("error", (err: NodeJS.ErrnoException) => {
583→			if (err.code === "EADDRINUSE") {
584→				console.warn(`[server] Port ${port} in use — OAuth callback skipped (manual paste still works)`);
585→			} else {
586→				console.error(`[server] OAuth callback server error (port ${port}):`, err);
587→			}
588→		});
589→		oauthCallbackServers.push(srv);
590→	}
591→
592→	// OpenAI: http://localhost:1455/auth/callback
593→	startOAuthCallbackServer(1455, "/auth/callback", "OAUTH_OPENAI_REDIRECT_URI");
594→	// Google Antigravity: http://localhost:51121/oauth-callback
595→	startOAuthCallbackServer(51121, "/oauth-callback", "OAUTH_ANTIGRAVITY_REDIRECT_URI");
596→
597→	// Graceful shutdown
598→	const gracefulShutdown = async (signal: string) => {
599→		console.log(`[server] Received ${signal}, shutting down gracefully...`);
600→		await taskQueueService.shutdown();
601→		await sessionPool.shutdown();
602→		for (const srv of oauthCallbackServers) srv.close();
603→		server.close(() => {
604→			console.log("[server] HTTP server closed");
605→			process.exit(0);
606→		});
607→		// Force exit after 10s if shutdown hangs
608→		setTimeout(() => process.exit(1), 10_000).unref();
609→	};
610→
611→	process.on("SIGTERM", () => gracefulShutdown("SIGTERM"));
612→	process.on("SIGINT", () => gracefulShutdown("SIGINT"));
613→
614→	server.listen(PORT, () => {
615→		console.log(`[server] Chatbot Platform running at http://localhost:${PORT}`);
616→		if (isDev) {
617→			console.log("[server] Running in development mode with Vite HMR");
618→		}
619→	});
620→}
621→
622→main().catch((err) => {
623→	console.error("Failed to start server:", err);
624→	process.exit(1);
625→});
