  1→/**
  2→ * S3-backed StorageService implementation.
  3→ *
  4→ * Uses AWS SDK v3. Requires S3_BUCKET_NAME env var.
  5→ * AWS credentials are resolved via the default credential chain
  6→ * (ECS task role in production, ~/.aws/credentials locally).
  7→ */
  8→
  9→import {
 10→	S3Client,
 11→	PutObjectCommand,
 12→	GetObjectCommand,
 13→	DeleteObjectCommand,
 14→	HeadObjectCommand,
 15→	ListObjectsV2Command,
 16→	DeleteObjectsCommand,
 17→} from "@aws-sdk/client-s3";
 18→import type { StorageService } from "./storage.js";
 19→
 20→export class S3StorageService implements StorageService {
 21→	private client: S3Client;
 22→	private bucket: string;
 23→
 24→	constructor(bucket: string, region?: string) {
 25→		this.bucket = bucket;
 26→		this.client = new S3Client({ region: region || process.env.AWS_REGION || "us-east-1" });
 27→	}
 28→
 29→	async upload(key: string, data: Buffer, contentType?: string): Promise<void> {
 30→		await this.client.send(
 31→			new PutObjectCommand({
 32→				Bucket: this.bucket,
 33→				Key: key,
 34→				Body: data,
 35→				ContentType: contentType || "application/octet-stream",
 36→			}),
 37→		);
 38→	}
 39→
 40→	async download(key: string): Promise<Buffer> {
 41→		const response = await this.client.send(
 42→			new GetObjectCommand({
 43→				Bucket: this.bucket,
 44→				Key: key,
 45→			}),
 46→		);
 47→		const stream = response.Body;
 48→		if (!stream) throw new Error(`Empty response for key: ${key}`);
 49→		// Collect stream into buffer
 50→		const chunks: Uint8Array[] = [];
 51→		for await (const chunk of stream as AsyncIterable<Uint8Array>) {
 52→			chunks.push(chunk);
 53→		}
 54→		return Buffer.concat(chunks);
 55→	}
 56→
 57→	async delete(key: string): Promise<void> {
 58→		await this.client.send(
 59→			new DeleteObjectCommand({
 60→				Bucket: this.bucket,
 61→				Key: key,
 62→			}),
 63→		);
 64→	}
 65→
 66→	async exists(key: string): Promise<boolean> {
 67→		try {
 68→			await this.client.send(
 69→				new HeadObjectCommand({
 70→					Bucket: this.bucket,
 71→					Key: key,
 72→				}),
 73→			);
 74→			return true;
 75→		} catch (err: any) {
 76→			if (err.name === "NotFound" || err.$metadata?.httpStatusCode === 404) {
 77→				return false;
 78→			}
 79→			throw err;
 80→		}
 81→	}
 82→
 83→	async listByPrefix(prefix: string): Promise<string[]> {
 84→		const keys: string[] = [];
 85→		let continuationToken: string | undefined;
 86→
 87→		do {
 88→			const response = await this.client.send(
 89→				new ListObjectsV2Command({
 90→					Bucket: this.bucket,
 91→					Prefix: prefix,
 92→					ContinuationToken: continuationToken,
 93→				}),
 94→			);
 95→			for (const obj of response.Contents || []) {
 96→				if (obj.Key) keys.push(obj.Key);
 97→			}
 98→			continuationToken = response.IsTruncated ? response.NextContinuationToken : undefined;
 99→		} while (continuationToken);
100→
101→		return keys;
102→	}
103→
104→	async deleteByPrefix(prefix: string): Promise<void> {
105→		const keys = await this.listByPrefix(prefix);
106→		if (keys.length === 0) return;
107→
108→		// DeleteObjects accepts max 1000 keys per request
109→		for (let i = 0; i < keys.length; i += 1000) {
110→			const batch = keys.slice(i, i + 1000);
111→			await this.client.send(
112→				new DeleteObjectsCommand({
113→					Bucket: this.bucket,
114→					Delete: {
115→						Objects: batch.map((Key) => ({ Key })),
116→						Quiet: true,
117→					},
118→				}),
119→			);
120→		}
121→	}
122→}
