  1→/**
  2→ * StorageService: abstraction for binary file storage.
  3→ *
  4→ * Phase 3 provides a local filesystem implementation.
  5→ * S3 backend deferred to Phase 5.
  6→ */
  7→
  8→import * as fs from "node:fs/promises";
  9→import * as path from "node:path";
 10→
 11→export interface StorageService {
 12→	upload(key: string, data: Buffer, contentType?: string): Promise<void>;
 13→	download(key: string): Promise<Buffer>;
 14→	delete(key: string): Promise<void>;
 15→	exists(key: string): Promise<boolean>;
 16→	/** List all keys under a given prefix (e.g. "skills/owner/name/") */
 17→	listByPrefix(prefix: string): Promise<string[]>;
 18→	/** Recursively delete all files under a given prefix */
 19→	deleteByPrefix(prefix: string): Promise<void>;
 20→}
 21→
 22→const DEFAULT_BASE_DIR = "./data/storage";
 23→
 24→export class LocalFsStorageService implements StorageService {
 25→	private baseDir: string;
 26→
 27→	constructor(baseDir?: string) {
 28→		this.baseDir = path.resolve(baseDir || DEFAULT_BASE_DIR);
 29→	}
 30→
 31→	private resolvePath(key: string): string {
 32→		const resolved = path.resolve(this.baseDir, key);
 33→		// Prevent path traversal
 34→		if (!resolved.startsWith(this.baseDir)) {
 35→			throw new Error("Invalid storage key");
 36→		}
 37→		return resolved;
 38→	}
 39→
 40→	async upload(key: string, data: Buffer, _contentType?: string): Promise<void> {
 41→		const filePath = this.resolvePath(key);
 42→		await fs.mkdir(path.dirname(filePath), { recursive: true });
 43→		await fs.writeFile(filePath, data);
 44→	}
 45→
 46→	async download(key: string): Promise<Buffer> {
 47→		const filePath = this.resolvePath(key);
 48→		return fs.readFile(filePath);
 49→	}
 50→
 51→	async delete(key: string): Promise<void> {
 52→		const filePath = this.resolvePath(key);
 53→		try {
 54→			await fs.unlink(filePath);
 55→		} catch (err: any) {
 56→			if (err.code !== "ENOENT") throw err;
 57→		}
 58→	}
 59→
 60→	async exists(key: string): Promise<boolean> {
 61→		const filePath = this.resolvePath(key);
 62→		try {
 63→			await fs.access(filePath);
 64→			return true;
 65→		} catch {
 66→			return false;
 67→		}
 68→	}
 69→
 70→	async listByPrefix(prefix: string): Promise<string[]> {
 71→		const dirPath = this.resolvePath(prefix);
 72→		const results: string[] = [];
 73→
 74→		const walk = async (dir: string) => {
 75→			let entries;
 76→			try {
 77→				entries = await fs.readdir(dir, { withFileTypes: true });
 78→			} catch (err: any) {
 79→				if (err.code === "ENOENT") return;
 80→				throw err;
 81→			}
 82→			for (const entry of entries) {
 83→				const fullPath = path.join(dir, entry.name);
 84→				if (entry.isDirectory()) {
 85→					await walk(fullPath);
 86→				} else if (entry.isFile()) {
 87→					// Return the key relative to baseDir
 88→					results.push(path.relative(this.baseDir, fullPath));
 89→				}
 90→			}
 91→		};
 92→
 93→		await walk(dirPath);
 94→		return results;
 95→	}
 96→
 97→	async deleteByPrefix(prefix: string): Promise<void> {
 98→		const dirPath = this.resolvePath(prefix);
 99→		try {
100→			await fs.rm(dirPath, { recursive: true, force: true });
101→		} catch (err: any) {
102→			if (err.code !== "ENOENT") throw err;
103→		}
104→	}
105→}
106→
107→export async function createStorageService(): Promise<StorageService> {
108→	const backend = process.env.STORAGE_BACKEND || "filesystem";
109→	if (backend === "filesystem") {
110→		return new LocalFsStorageService(process.env.STORAGE_BASE_DIR);
111→	}
112→	if (backend === "s3") {
113→		const bucket = process.env.S3_BUCKET_NAME;
114→		if (!bucket) throw new Error("S3_BUCKET_NAME is required when STORAGE_BACKEND=s3");
115→		const { S3StorageService } = await import("./s3-storage.js");
116→		return new S3StorageService(bucket, process.env.AWS_REGION);
117→	}
118→	throw new Error(`Unknown STORAGE_BACKEND: ${backend}. Supported: "filesystem", "s3".`);
119→}
