36→			"ENCRYPTION_ROOT_KEY must be set to a 64-character hex string (32 bytes)",
37→		);
38→	}
39→	const rootKey = Buffer.from(rootKeyHex, "hex");
40→
41→	function wrapDek(dek: Buffer): Buffer {
42→		const iv = randomBytes(IV_LENGTH);
43→		const cipher = createCipheriv(ALGORITHM, rootKey, iv);
44→		const encrypted = Buffer.concat([cipher.update(dek), cipher.final()]);
45→		const authTag = cipher.getAuthTag();
46→		// Format: IV (12) + encrypted DEK (32) + authTag (16)
47→		return Buffer.concat([iv, encrypted, authTag]);
48→	}
49→
50→	function unwrapDek(wrappedDek: Buffer): Buffer {
51→		const iv = wrappedDek.subarray(0, IV_LENGTH);
52→		const encrypted = wrappedDek.subarray(IV_LENGTH, IV_LENGTH + DEK_LENGTH);
53→		const authTag = wrappedDek.subarray(IV_LENGTH + DEK_LENGTH, IV_LENGTH + DEK_LENGTH + AUTH_TAG_LENGTH);
54→
55→		const decipher = createDecipheriv(ALGORITHM, rootKey, iv);
56→		decipher.setAuthTag(authTag);
57→		return Buffer.concat([decipher.update(encrypted), decipher.final()]);
58→	}
