		});

		// ----------------------------------------------------------------
		// ECR — container registry
		// ----------------------------------------------------------------
		const repository = new ecr.Repository(this, "AppRepository", {
			repositoryName: "chatbot-platform",
			removalPolicy: cdk.RemovalPolicy.RETAIN,
			lifecycleRules: [
