				APP_URL: props.domainName ? `https://${props.domainName}` : "",
				REGISTRATION_MODE: "open",
			},
			secrets: {
				// Inject individual secret fields as env vars
				JWT_SECRET: ecs.Secret.fromSecretsManager(appSecrets, "JWT_SECRET"),
